 赋值操作符函数、特殊类对象处理 # 赋值操作符函数的正确写法 # Computer.cc
// Computer.h #ifndef __COMPUTER_H__ #define __COMPUTER_H__ class Computer { public: Computer(const char *brand, float price); Computer(const Computer &amp;rhs); Computer &amp;operator=(const Computer &amp;rhs); void setBrand(const char *brand); void setPrice(float price); void print(); ~Computer(); private: char *_brand; float _price; }; #endif 我们一步一步讨论赋值操作符函数的写法：
Computer &amp;Computer::operator=(const Computer &amp;rhs) { cout &lt;&lt; &#34;Computer &amp;operator=(const Computer &amp;)&#34; &lt;&lt; endl; #if 0 // V1: // 此时等号左边的对象与右边的对象指向同一个地址 // ERROR: 每一个对象的_brand存同一个地址，在回收资源时都调用一次析构函数 // ERROR: 这就对同一个地址free了两次，造成错误 // 所以当有堆空间时候，不可这么写 _brand = rhs._brand; _price = rhs._price; #endif #if 0 // V2: // 原先的深拷贝空间哪去了？初始化时候根据初始化的值申请了一个空间 // 重新赋值调用此处时，如果旧空间够用，那么可以继续使用旧空间 strcpy(_brand, rhs._brand); _price = rhs._price; #endif #if 0 // V3 // 如果不够用，为了不被截断，出现意料之外的结果 // 就需要给_brand重新分配空间 if (strlen(this-&gt;_brand) &lt; strlen(rhs._brand)) { delete[] _brand; _brand = new char[strlen(rhs._brand) + 1](); } strcpy(this-&gt;_brand, rhs._brand); this-&gt;_price = rhs._price; #endif #if 1 // V4 // 但是此时如果出现自复制com1 = com1的话，会出现 // strcpy(a._brand, a._brand); // 源和目标是同一地址 // strcpy 对重叠内存区域的行为是 未定义行为（C 标准明确禁止 restrict // 指针重叠）。同一地址在实现上通常不会出错（从左往右拷贝，覆盖前已读完） // 但标准不保证。 if (this != &amp;rhs) { // 自赋值直接跳过 if (strlen(this-&gt;_brand) &lt; strlen(rhs._brand)) { delete[] _brand; _brand = new char[strlen(rhs._brand) + 1](); } strcpy(this-&gt;_brand, rhs._brand); this-&gt;_price = rhs._price; } #endif return *this; } 同时，关于析构函数中 delete 的写法，其实，析构调用时，意味着对象马上就没了，所以既不用在同一个对象上判空避免二次 free，delete 后也无需赋 nullptr。但是这是个好习惯。
Computer::~Computer() { cout &lt;&lt; &#34;~Computer()&#34; &lt;&lt; endl; /* if(_brand != nullptr) */ // if (_brand) { // 用来防止同一个对象是否被析构两次，编译器自动的，没有必要 /* cout &lt;&lt; &#34;delete [] _brand&#34; &lt;&lt; endl; */ delete[] _brand; // _brand = nullptr; // } } 赋值操作符函数三问 # Point2.cc
// 赋值操作符函数实际写法 Point &amp;operator=(const Point &amp;rhs) { cout &lt;&lt; &#34;Point &amp;operator=(const Point &amp;)&#34; &lt;&lt; endl; _ix = rhs._ix;//赋值 _iy = rhs._iy; return *this; } 赋值构造函数参数中的 &amp; 能被去掉吗？ # // 默认情况下编译器会自动生成赋值运算符函数 // pt2 = pt1; // Q：引用符号可以去掉吗？ // 如果去掉，会变为如下 Point &amp;operator=(const Point rhs) { cout &lt;&lt; &#34;Point &amp;operator=(const Point &amp;)&#34; &lt;&lt; endl; _ix = rhs._ix;//赋值 _iy = rhs._iy; return *this; } Point P1; Point P2; // 此时调用赋值运算符函数 P2 = P1; // 调用赋值运算符函数，由于参数值传递，将 P1 值赋值给 rhs // 此时，const Point rhs = P1; // 用已经存在的对象给新对象赋值，触发拷贝构造函数调用 // 拷贝构造函数 Point(const Point &amp;rhs)//Point pt2 = pt1 : _ix(rhs._ix) , _iy(rhs._iy) { cout &lt;&lt; &#34;Point(const Point &amp;)&#34; &lt;&lt; endl; } // 拷贝构造函数参数为 const Point&amp; rhs = P1 // 拷贝构造函数将引用 P1 的 rhs 的值赋值给了赋值运算符参数中的非引用 rhs // 答：如果去掉，会多执行一次拷贝构造函数，效率就会降低 赋值构造函数的参数中的 const 能否被去掉呢？ # // Q:const可以去掉吗： // 如果去掉，赋值运算符函数就变成了: Point &amp;operator=(Point &amp;rhs) { cout &lt;&lt; &#34;Point &amp;operator=(const Point &amp;)&#34; &lt;&lt; endl; _ix = rhs._ix;//赋值 _iy = rhs._iy; return *this; } Point func() { Point p3; return p3; } void test5() { Point p4; // 赋值构造函数如果没有 const，p4 将变成非 const， // 无法绑定到临时对象这种右值 p4 = func(); ERROR: &#34;No viable overloaded &#39;=&#39; &#34; } // 答：如果去掉 const，右操作数是右值的时候，就会产生非 const 左值引用不能绑定到右值的报错 赋值构造函数的返回类型能否是 void？ # // Q:赋值运算符函数的返回类型可以是void？ // 如果去掉，赋值运算符函数就变成了: void operator=(const Point &amp;rhs) { cout &lt;&lt; &#34;Point &amp;operator=(const Point &amp;)&#34; &lt;&lt; endl; _ix = rhs._ix;//赋值 _iy = rhs._iy; return *this; } Point p5; Point p6; Point p7; p5 = p6 = p7; // 语句会有语法错误 // 先执行 p6 = p7 没有问题，然后返回了 void 类型 // 此时将执行 p5 = void 类型的值将出现问题 // A:考虑连等情况 类内特殊成员处理 # 有四类比较特殊的类对象需要单独处理，分别是类内常量数据成员、类内引用数据成员、类内类对象数据成员和静态类内数据成员。
类内常量数据成员 # const 修饰的对象，无论在类内还是类外，都需要在声明时候就直接赋值。在类内做数据成员时，需要在构造函数的初始化列表中进行初始化，而不能在构造函数体内进行。
#include &lt;iostream&gt; using std::cout; using std::endl; class Point { public: Point(int ix = 0, int iy = 0) : _ix(ix) , _iy(iy) { cout &lt;&lt; &#34;Point(int = 0, int = 0)&#34; &lt;&lt; endl; /* _ix = ix;//error,赋值 */ /* _iy = iy; */ } void print() { cout &lt;&lt; &#34;(&#34; &lt;&lt; _ix &lt;&lt; &#34;, &#34; &lt;&lt; _iy &lt;&lt; &#34;)&#34; &lt;&lt; endl; } ~Point() { cout &lt;&lt; &#34;~Point()&#34; &lt;&lt; endl; } private: const int _ix;//常量数据成员,必须在初始化列表中进行 const int _iy; }; 类内引用数据成员 # 同理，由于引用也必须在声明时初始化，也需要在初始化列表中进行初始化。
#include &lt;iostream&gt; using std::cout; using std::endl; class Point { public: Point(int ix = 0, int iy = 0) : _ix(ix) , _iy(iy) , _ref(_ix) { cout &lt;&lt; &#34;Point(int = 0, int = 0)&#34; &lt;&lt; endl; /* _ix = ix;//error,赋值 */ /* _iy = iy; */ } void print() { cout &lt;&lt; &#34;(&#34; &lt;&lt; _ix &lt;&lt; &#34;, &#34; &lt;&lt; _iy &lt;&lt; &#34;)&#34; &lt;&lt; endl; } ~Point() { cout &lt;&lt; &#34;~Point()&#34; &lt;&lt; endl; } private: int _ix; int _iy; int &amp;_ref; }; //成员函数不占用类的大小，成员函数存在于程序代码区，被该类的 //左右对象共享 // int main(int argc, char **argv) { cout &lt;&lt; &#34;sizeof(Point) = &#34; &lt;&lt; sizeof(Point) &lt;&lt; endl; Point pt(1, 2);//栈对象 return 0; } 辨析：引用数据类型是否占用内存空间？
通过sizeof(Point) 我们可以测出，只有两个 int 的类大小和多了一个引用变量的类大小：
// 没有引用变量_ref sizeof(Point) = 8 // 有引用变量_ref sizeof(Point) = 16 测试结果表明，类内引用类型的数据成员变量占用了内存空间，而且是8个字节大小的指针；且可以说明，函数不占类的空间。进一步的，函数是存在程序段中的。
结论： C++ 标准（[dcl.ref]）原文：
It is unspecified whether or not a reference requires storage.
也就是说，引用是否占用存储是&quot;未指定&quot;的——编译器在不需要存储时可以不分配，在必须时则分配。
实验正确证明了&quot;引用作为类成员时按指针大小占 8 字节&quot;，但这属于标准允许的&quot;实现需要存储&quot;的情形；局部引用和参数引用在底层常被消除或仅暂存于寄存器，所以不能笼统说&quot;引用一定占内存&quot;。
类内类对象数据成员 # 类内对象在被初始化时，要注意会调用其自身的构造函数，资源回收时，会调用自身的析构函数。
#include &lt;iostream&gt; using std::cout; using std::endl; class Point { public: /* Point(int ix = 0, int iy = 0) */ Point(int ix, int iy) : _ix(ix) , _iy(iy) { cout &lt;&lt; &#34;Point(int = 0, int = 0)&#34; &lt;&lt; endl; } void print() { cout &lt;&lt; &#34;(&#34; &lt;&lt; _ix &lt;&lt; &#34;, &#34; &lt;&lt; _iy &lt;&lt; &#34;)&#34; &lt;&lt; endl; } ~Point() { cout &lt;&lt; &#34;~Point()&#34; &lt;&lt; endl; } private: int _ix; int _iy; }; class Line { public: Line(int x1, int y1, int x2, int y2) : _pt1(x1, y1)//类对象成员需要显示进行初始化，否则就是默认值 , _pt2(x2, y2) { cout &lt;&lt; &#34;Line(int, int, int,int)&#34; &lt;&lt; endl; } void printLine() { _pt1.print(); _pt2.print(); } ~Line() { cout &lt;&lt; &#34;~Line()&#34; &lt;&lt; endl; } private: Point _pt1;//类对象成员(子对象) Point _pt2; }; int main(int argc, char **argv) { Line line(1, 2, 3, 4); line.printLine(); return 0; } // 输出如下： // 两个对象，因此，每个对象被创建时都调用了一次构造函数 Point(int = 0, int = 0) Point(int = 0, int = 0) Line(int, int, int,int) (1, 2) (3, 4) ~Line() // 两个对象，因此，每个对象被销毁都调用了一次析构函数 ~Point() ~Point() 类内静态数据成员 # 类内定义静态成员时，需要在类外全局静态区域进行初始化。该静态数据成员存储在内存的全局静态区，所有的类对象，共享一份静态数据成员变量。 对于头文件和实现文件分开的代码方式，为了避免重定义的问题，全局变量的初始化应放在 .cc 的实现文件中，而非头文件中。
四个特殊数据成员中，唯有静态数据成员不能放在构造函数的初始化列表中初始化
#include &lt;cstring&gt; #include &lt;iomanip&gt; #include &lt;iostream&gt; #include &lt;stdlib.h&gt; class TestClass { // 不占类空间，直接放在全局静态区被类对象共享 static float _totalPrice; char *_brand; float _price; public: TestClass(char *brand, float price) : _brand(new char[strlen(brand) + 1]()), _price(price) /*,_totalPrice(0.0)*/ {} ~TestClass() {} void caculateSum() { _totalPrice += _price; } void printSum() { std::cout &lt;&lt; std::fixed &lt;&lt; std::setprecision(2) &lt;&lt; _totalPrice &lt;&lt; std::endl; } }; // 这里不能加 `static` 修饰符 float TestClass::_totalPrice = 0; int main() { TestClass tc1(&#34;mac&#34;, 12000); tc1.caculateSum(); tc1.printSum(); TestClass tc2(&#34;huawei&#34;, 1200000); tc2.caculateSum(); tc2.printSum(); // 由于内存对齐机制，大小为 16; 将 float 换成 double 也是 16 std::cout &lt;&lt; &#34;the size of TestClass is &#34; &lt;&lt; sizeof(TestClass) &lt;&lt; std::endl; return 0; } 关于头文件卫士： 我们经常在头文件中写
#ifndef __COMPUTER_H__ #define __COMPUTER_H__ // 头文件的内容 #endif 这是为了避免在同一个.cc文件中多次包含某一个头文件造成重复定义的问题。 我们想要的效果就是每一个包含该头文件的.cc文件都包含一次这个头文件，以便可以正常通过编译。 当多个.o文件都有一份定义时候，那么会出现链接错误。
如果你想更仔细的了解，那么这篇文章也许比较适合你：重定义错误并不“显然”

 重载、强制类型转换、内联函数、C 风格和 C++风格的字符串、内存分配 # 强制类型转换 # 在c语言中，强制类型转换通过括号就能实现，非常自由，也非常不安全。为了避免强制类型转换出现的问题，C++ 创造了四种强制类型转换运算符来告诉编译器你的意图，从而让编译器最大可能对你提醒。
四种 C++ cast 把不同语义拆分出去: # 让能安全的被编译器保护（static_cast）， 可能有危险的危险转换的被显式标注（const_cast、reinterpret_cast）， 能运行时检查的就做运行时检查（dynamic_cast）。 C 风格括号搞定一切，等于一个工具干四种完全不同语义的活，编译器无法根据你的意图做任何区分检查。 C 的不安全在于，强制转换无论是内置类型之间还是内置类型和指针之间都可以随意转换。我们举例子说明：
1. 错误地将 double* 转成 int* # C 风格——编译通过，运行时完全错误：
double d = 3.14; int* p = (int*)&amp;d; // 编译通过，但把浮点数的二进制当整数读，结果完全错误 int x = *p; // 未定义行为 C++ static_cast——直接编译失败：
double d = 3.14; int* p = static_cast&lt;int*&gt;(&amp;d); // 编译错误：static_cast 不允许无关指针类型互转 static_cast 在编译期就发现 double* 和 int* 之间不存在合法的转换路径，直接拒绝。 如果你真的非要做（尽管这是错的），唯一的途径是：
int* p = reinterpret_cast&lt;int*&gt;(&amp;d); // 编译通过，但 `reinterpret_cast` 这个名字就是红色警报 代码中看到 reinterpret_cast，审阅者立刻知道这里有危险操作，不会被轻易放过。
2. 悄悄去除 const 属性 # C 风格——const 被无声吞掉：
void modify(const int* cip) { int* p = (int*)cip; // const 丢了，没有任何警告 *p = 42; // 未定义行为，编译器帮不了你 } int main() { const int n = 10; modify(&amp;n); // n 明明声明为 const，值却被改了，程序逻辑完全混乱 } C++ const_cast——意图被显式标记，且可能根本不该用：
void modify(const int* cip) { int* p = const_cast&lt;int*&gt;(cip); // &#34;const_cast&#34; 四个字就是危险标签，你没法滥用而不自知 *p = 42; // ⚠️ 如果 cip 真的指向一个 const 变量，这仍然是未定义行为 } int main() { const int n = 10; modify(&amp;n); // 问题仍然存在，但审查代码时一眼就看到 const_cast } 更进一步：C++ 的做法是根本不用 const_cast，而是区分只读和可写：
// 如果参数确实是只读的，就用 const int* void print_only(const int* p) { printf(&#34;%d\n&#34;, *p); // 不需要转换 } // 如果参数需要修改，就接受非 const 参数 void modify(int* p) { *p = 42; } 类型系统替你挡掉错误调用——const int* 根本传不进去 modify。
3. 沿继承链的错误向下转型 # C 风格——不安全转换导致崩溃：
struct Base { int x; }; struct Derived { int x; int y; }; Base* b = malloc(sizeof(Base)); b-&gt;x = 10; Derived* d = (Derived*)b; // b 根本不是 Derived，编译完全不拦 int val = d-&gt;y; // 访问不存在的成员，运行时 crash 或读到脏数据 C++ dynamic_cast——运行时检测，失败返回 nullptr： struct Base { virtual ~Base() = default; // 需要虚函数以启用 RTTI }; struct Derived : Base { int y = 42; }; Base* b = new Base; Derived* d = dynamic_cast&lt;Derived*&gt;(b); // 运行时检查：b 不是 Derived if (d == nullptr) { // 安全处理失败情况 } else { int val = d-&gt;y; // 只有转换成功才执行，不会访问无效内存 } dynamic_cast 查虚表发现 b 的真实类型是 Base，拒绝转换并返回 nullptr。 如果用 static_cast 做同样的事：
Derived* d = static_cast&lt;Derived*&gt;(b); // 编译通过，但这是“你向我保证 b 是 Derived” d-&gt;y; // 你撒谎了，未定义行为——和 C 风格一样不安全 区别在于 static_cast 的名字在告诉你：“我在做一个静态假设，没有运行时检查，请确保你的逻辑是对的”。
inline 内联函数 # inline函数只是给编译器的一个建议，编译器如果发现你建议是 inline类型的函数会使代码变得臃肿，它就不会接受你的建议。
inline 只是请求，编译器在以下情况会忽略它，生成普通 call 指令：
情况 原因 函数体过大 内联会导致代码膨胀，反而降低 I-cache 命中率 递归函数 不可能完全展开（除非尾递归编译器能优化时） 函数地址被取 必须有独立地址才能取 &amp;add 虚函数调用 运行时通过虚表分发，编译期不知道具体函数 包含循环/复杂分支 编译器认为不值得内联 -O0 优化级别 不开启优化时基本不内联 显式禁止 attribute((noinline)) 或 [[gnu::noinline]] 可用 g++ -Winline 看到编译器放弃内联的警告。
// 递归函数，编译器会把其作为普通函数对待 inline int TestInline_1(int n) { if(n == 1) { return 0; } if (n == 2) { return 1; } return TestInline_1(n - 1) + TestInline_1(n - 2); } int main() { TestInline_1(); return 0; } | | | | V V int main() { // 普通函数调用 TestInline_1(4); return 0; } 从本质上说，inline函数是为了省去函数调用的开销，直接将函数体替换到调用位置，但是其与带参宏定义又不同，因为内联函数在编译期处理，宏定义在预处理阶段做文本替换；内联函数有类型检查，宏定义没有；内联函数可设断点调试，宏定义不可以；具体还有如下不同：
内联函数 带参宏 处理阶段 编译期（编译器） 预处理期（文本替换） 类型检查 ✅ 有 ❌ 无 参数求值次数 1 次（正常函数语义） N 次（每处引用就展开一次） 作用域 遵循命名空间、类作用域 无作用域概念 重载 ✅ 支持 ❌ 不支持 可调试 ✅ 可设断点 ❌ 无法调试 地址 有（编译器可保留一份） 无 #/## 操作符 ❌ 不支持 ✅ 支持 R // testInline.cc, 若inline函数太臃肿，编译器会把其作为普通函数对待 inline void TestInline_1 (int a, int b) { cout &lt;&lt; &#34;a + b = &#34; &lt;&lt; a + b &lt;&lt; endl; } int main() { TestInline_1(); return 0; } | | | | V V int main() { // inline直接替换了 cout &lt;&lt; &#34;a + b = &#34; &lt;&lt; a + b &lt;&lt; endl; return 0; } // 宏定义只做文本替换的例子 #include &lt;iostream&gt; #define ADD(x, y) {return (x) + (y);} inline int add(int x, int y) {return x + y;} int main(int argc, char *argv[]) { #if 0 // main 函数提前返回 ADD(3, 4); // 无法输出下面这句 std::cout &lt;&lt; &#34;hi&#34; &lt;&lt; std::endl; #endif add(3,4); // 正常输出 std::cout &lt;&lt; &#34;hi&#34; &lt;&lt; std::endl; return 0; } 关于#/##：不过现代 C++ 中用得越来越少——模板、if constexpr、反射（C++26）在很多场景可以替代宏拼接。# 在断言/日志中还算常见，## 主要出现在那些不得不操作标识符名的底层框架代码里。
由于inline做的是直接将函数体放在调用位置的工作，因此，要在同一个文件中同时找到声明和实现
在同一个文件：
// math.h #pragma once inline int add(int a, int b) { return a + b; } // 声明+定义都在头文件 // main.cpp #include &#34;math.h&#34; int main() { return add(1, 2); } // 能看到函数体，可内联 ✅ // other.cpp #include &#34;math.h&#34; int other() { return add(3, 4); } // ✅ 也不会报重定义，因为有 inline 声明和实现在不同的文件，那就把他们拉到同一个文件中来:
// math.h #pragma once inline int add(int a, int b); // 声明 #include &#34;math.ipp&#34; // 把定义&#34;拉进来&#34; // math.ipp inline int add(int a, int b) { return a + b; } // 定义 // main.cpp — 只需包含 .h #include &#34;math.h&#34; // math.ipp 的内容被拉进 main.cpp，函数体可见 ✅ 实现和声明不在同一个文件中时，会报错：
