值 */ int const number2 = 20; } //函数指针 指针函数 //int (*pf)(int) int* pf(int) // //数组指针 指针数组 //int (*pArray)[] int* pArray[] void test2() { int value = 2; int value1 = 10; int *p1 = &amp;value1; p1 = &amp;value; *p1 = 20000; cout &lt;&lt; endl; int value2 = 200; const int *p2 = &amp;value2;//当const位于*左边的时候，常量指针(pointer to const) /* *p2 = 222;//error,不能修改指针所指变量的值 */ p2 = &amp;value;//ok,可以改变指针本身（指向） cout &lt;&lt; endl; int value3 = 300; int const *p3 = &amp;value3;//当const位于*左边的时候，常量指针(pointer to const) /* *p3 = 333;//error,不能修改指针所指变量的值 */ p3 = &amp;value;//ok,可以改变指针本身（指向） cout &lt;&lt; endl; int value4 = 400; int * const p4 = &amp;value4;//当const位于*右边的时候，指针常量(const pointer) *p4 = 444;//ok,可以修改指针所指变量的值 /* p4 = &amp;value;//error,不可以改变指针本身（指向） */ cout &lt;&lt; endl; int value5 = 500; const int * const p5 = &amp;value5;//双const /* *p5 = 555;//error,不可以修改指针所指变量的值 */ /* p5 = &amp;value;//error,不可以改变指针本身（指向） */ } int main(int argc, char **argv) { test2(); return 0; } new和delete # new/delete与malloc/free的区别是什么?
