tf(&#34;ref = %p\n&#34;, &amp;ref); cout &lt;&lt; endl; //引用的实质：指针常量 * const //引用不能独立存在，在定义的时候必须要进行初始化,在定义的 //的时候绑定到变量上面，跟变量绑定到一起，不会改变引用的指向 /* int &amp;ref2; ERROR */ } //1、引用作为函数参数 #if 0 //值传递====副本 //没有触及a b本身 void swap(int x, int y)//int x = a, int y = b { int temp = x; x = y; y = temp; } #endif #if 0 //值传递====地址值 void swap(int *px, int *py)//int *px = &amp;a, int *py = &amp;b; { int temp = *px; *px = *py; *py = temp; } #endif //引用传递====变量本身 void swap(int &amp;x, int &amp;y)//int &amp;x = a, int &amp;y = b { int temp = x; x = y; y = temp; } void test2() { int a = 3, b = 4; cout &lt;&lt; &#34;在交换之前 a = &#34; &lt;&lt; a &lt;&lt; &#34;, b = &#34; &lt;&lt; b &lt;&lt; endl; swap(a, b); cout &lt;&lt; &#34;在交换之后 a = &#34; &lt;&lt; a &lt;&lt; &#34;, b = &#34; &lt;&lt; b &lt;&lt; endl; } //2、引用作为函数返回类型 int func1() { int number = 10; return number;//执行一个拷贝操作 } int &amp;func2() { int number = 10;//局部变量 return number;//不能返回一个局部变量的引用 } //不要去返回堆空间的引用,必须要有内存回收的机制 int &amp;getHeapData() { int *pInt = new int(100); return *pInt; } void test4() { int a = 3, b = 5; int temp = a + getHeapData() + b; cout &lt;&lt; &#34;temp = &#34; &lt;&lt; temp &lt;&lt; endl; int &amp;ref = getHeapData(); delete &amp;ref; } //函数返回类型是引用的前提:实体的生命周期一定要大于函数的生命周期 int arr[10] = {1, 3, 5, 7, 9, 10}; int &amp;getIndex(int idx) { return arr[idx];//先不去考虑越界 } void test3() { cout &lt;&lt; &#34;getIndex(0) = &#34; &lt;&lt; getIndex(0) &lt;&lt; endl; getIndex(0) = 200; cout &lt;&lt; &#34;getIndex(0) = &#34; &lt;&lt; getIndex(0) &lt;&lt; endl; cout &lt;&lt; &#34;arr[0] = &#34; &lt;&lt; arr[0] &lt;&lt; endl; /* func1() = 200; */ } int main(int argc, char **argv) { test4(); return 0; } Day1作业 # C++Day1
